<?php
if(!defined('ABSPATH'))exit;
add_action('init',function(){register_post_type('dgs_video',array('label'=>'گالری ویدیوها','public'=>false,'show_ui'=>true,'show_in_menu'=>'dgs-setup','supports'=>array('title','excerpt','thumbnail','page-attributes'),'capability_type'=>'post','capabilities'=>array('edit_posts'=>'manage_options','create_posts'=>'manage_options','delete_posts'=>'manage_options')));},9);
function dgs_video_url(){$pages=get_option('dgs_pages',array());return !empty($pages['videos'])?get_permalink($pages['videos']):add_query_arg('dgs_videos','1',home_url('/'));}
function dgs_video_active(){$p=get_option('dgs_pages',array());return (!empty($p['videos'])&&is_page((int)$p['videos']))||dgs_att_get('dgs_videos')==='1';}
add_action('admin_init',function(){if(!current_user_can('manage_options'))return;$p=get_option('dgs_pages',array());if(!empty($p['videos'])&&get_post_status($p['videos'])==='publish')return;$found=get_posts(array('post_type'=>'page','meta_key'=>'_dgs_page_key','meta_value'=>'videos','numberposts'=>1));$id=$found?$found[0]->ID:wp_insert_post(array('post_type'=>'page','post_status'=>'publish','post_title'=>'گالری ویدیوهای مدرسه','post_name'=>'school-videos','post_content'=>'[daneshgaran_videos]','meta_input'=>array('_dgs_page_key'=>'videos')));if($id&&!is_wp_error($id)){$p['videos']=(int)$id;update_option('dgs_pages',$p);}},45);
function dgs_video_revision($id){if(!$id)return '';$p=get_post($id);return $p?hash('sha256',wp_json_encode(array($p->post_title,$p->post_status,$p->post_excerpt,$p->menu_order,get_post_meta($id,'_dgs_aparat',true),get_post_thumbnail_id($id)))):'';}
function dgs_video_save($d,$image=0){
 if(!current_user_can('dgs_manage_education'))return dgs_edu_error('access','فقط مدیر و معاون اجازه دارند.');foreach($d as $v)if(!is_scalar($v))return dgs_edu_error('input','فرم معتبر نیست.');$id=absint($d['id']??0);$p=$id?get_post($id):null;if($id&&(!$p||$p->post_type!=='dgs_video'||!in_array($p->post_status,array('publish','draft'),true)))return dgs_edu_error('scope','ویدیو معتبر نیست.');
 $lock='dgs_video_'.($id?:get_current_user_id());if(!add_option($lock,time(),'','no'))return dgs_edu_error('busy','ذخیره دیگری در جریان است.');try{
 if($id&&!hash_equals(dgs_video_revision($id),(string)($d['revision']??'')))return dgs_edu_error('stale','ویدیو تغییر کرده؛ صفحه را تازه کنید.');
 if(($d['operation']??'')==='delete'){if(!$id||!wp_trash_post($id))return dgs_edu_error('delete','حذف انجام نشد.');dgs_video_purge();return $id;}
 $source=dgs_teacher_video_source((string)($d['aparat']??''));$title=sanitize_text_field((string)($d['title']??''));$status=$d['status']??'draft';$description=sanitize_textarea_field((string)($d['description']??''));if(!$source||$source['type']!=='aparat'||!$title||dgs_edu_length($title)>200||dgs_edu_length($description)>3000||!in_array($status,array('publish','draft'),true))return dgs_edu_error('fields','عنوان، لینک ویدیوی آپارات و وضعیت معتبر را وارد کنید.');
 if($image&&!dgs_showcase_image_valid($image))return dgs_edu_error('image','عکس جلد معتبر نیست.');$thumb=$image?:($id?get_post_thumbnail_id($id):0);if(($d['remove_image']??'')==='1'&&!$image)$thumb=0;
 $row=['post_type'=>'dgs_video','post_title'=>$title,'post_excerpt'=>$description,'post_status'=>$status,'menu_order'=>max(0,min(9999,(int)($d['order']??0))),'meta_input'=>['_dgs_aparat'=>$source['url'],'_thumbnail_id'=>$thumb]];if($id)$row['ID']=$id;$saved=wp_insert_post(wp_slash($row),true);if(is_wp_error($saved))return $saved;dgs_video_purge();dgs_edu_audit('video_save',$saved);return $saved;
 }finally{delete_option($lock);}
}
function dgs_video_purge(){dgs_school_photos_purge();$p=get_option('dgs_pages',array());if(!empty($p['videos'])){clean_post_cache($p['videos']);do_action('litespeed_purge_post',(int)$p['videos']);}}
add_action('admin_post_dgs_video',function(){if(!current_user_can('dgs_manage_education')||($_SERVER['REQUEST_METHOD']??'')!=='POST')wp_die('دسترسی ندارید.','',array('response'=>403));check_admin_referer('dgs_video');$d=wp_unslash($_POST);$image=($d['operation']??'')==='delete'?0:dgs_news_photo();$r=is_wp_error($image)?$image:dgs_video_save($d,$image);if(is_wp_error($r)&&is_int($image)&&$image)wp_delete_attachment($image,true);$token=wp_generate_password(24,false,false);set_transient('dgs_edu_flash_'.get_current_user_id().'_'.$token,['error'=>is_wp_error($r),'text'=>is_wp_error($r)?$r->get_error_message():'ویدیو ذخیره شد.'],300);$args=['dg_notice'=>$token];if(is_wp_error($r))$args['video_edit']=absint($d['id']??0)?:'new';wp_safe_redirect(dgs_school_url('videos',dgs_edu_current_year(),$args),303);exit;});
function dgs_video_form($id=0,$op='save'){return '<form class="dgx-form" method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'">'.wp_nonce_field('dgs_video','_wpnonce',true,false).'<input type="hidden" name="action" value="dgs_video"><input type="hidden" name="operation" value="'.esc_attr($op).'"><input type="hidden" name="id" value="'.(int)$id.'"><input type="hidden" name="revision" value="'.esc_attr(dgs_video_revision($id)).'">';}
function dgs_edu_view_videos($year){
 if(!current_user_can('dgs_manage_education'))return '';$edit=dgs_att_get('video_edit');$h='<div class="dsp-school">'.dgs_extension_title('گالری ویدیوها','videos','لینک آپارات، عکس جلد، ترتیب و انتشار ویدیو را مدیریت کنید.').'<section class="dsp-card">';
 if($edit!==''){$id=$edit==='new'?0:absint($edit);$p=$id?get_post($id):null;if($id&&(!$p||$p->post_type!=='dgs_video'||!in_array($p->post_status,['draft','publish'],true)))return $h.dgs_empty('ویدیو پیدا نشد.').'</section></div>';$h.=dgs_video_form($id).'<label>عنوان<input name="title" required maxlength="200" value="'.esc_attr($p?$p->post_title:'').'"></label><label>لینک ویدیو در آپارات<input name="aparat" type="url" dir="ltr" required placeholder="https://www.aparat.com/v/otv499p" value="'.esc_attr($id?get_post_meta($id,'_dgs_aparat',true):'').'"></label><label>توضیح کوتاه<textarea name="description" maxlength="3000">'.esc_textarea($p?$p->post_excerpt:'').'</textarea></label><label>عکس جلد (اختیاری)<input type="file" name="news_photo" accept="image/jpeg,image/png,image/webp"></label>';if($id&&has_post_thumbnail($id))$h.=get_the_post_thumbnail($id,'thumbnail').'<label><input type="checkbox" name="remove_image" value="1">برداشتن جلد</label>';
 return $h.'<label>ترتیب<input type="number" min="0" max="9999" name="order" value="'.($p?(int)$p->menu_order:0).'"></label>'.dgs_edu_select('status','وضعیت',['draft'=>'پیش‌نویس','publish'=>'منتشرشده'],$p?$p->post_status:'draft').'<button class="dg-btn">ذخیره ویدیو</button></form><a href="'.esc_url(dgs_school_url('videos',$year)).'">بازگشت به فهرست</a></section></div>';}
 $page=max(1,absint(dgs_att_get('video_page','1')));$q=new WP_Query(['post_type'=>'dgs_video','post_status'=>['draft','publish'],'posts_per_page'=>20,'paged'=>$page,'orderby'=>['menu_order'=>'ASC','ID'=>'DESC']]);$h.='<a class="dg-btn" href="'.esc_url(dgs_school_url('videos',$year,['video_edit'=>'new'])).'">افزودن ویدیو</a>'.dgs_edu_table_start(['عنوان','وضعیت','عملیات']);foreach($q->posts as $p)$h.='<tr><td>'.esc_html($p->post_title).'</td><td>'.($p->post_status==='publish'?'منتشرشده':'پیش‌نویس').'</td><td><a href="'.esc_url(dgs_school_url('videos',$year,['video_edit'=>$p->ID])).'">ویرایش</a>'.dgs_video_form($p->ID,'delete').'<button class="dge-small-btn" data-dgx-confirm="ویدیو از سایت حذف شود؟">حذف</button></form></td></tr>';$h.='</tbody></table></div>';if($page>1)$h.='<a href="'.esc_url(dgs_school_url('videos',$year,['video_page'=>$page-1])).'">قبلی</a>';if($page<$q->max_num_pages)$h.='<a href="'.esc_url(dgs_school_url('videos',$year,['video_page'=>$page+1])).'">بعدی</a>';return $h.'</section></div>';
}
function dgs_video_cards($limit=3,$page=1){$q=new WP_Query(['post_type'=>'dgs_video','post_status'=>'publish','posts_per_page'=>$limit,'paged'=>$page,'orderby'=>['menu_order'=>'ASC','ID'=>'DESC']]);$h='<div class="dgx-video-grid">';foreach($q->posts as $p){$source=dgs_teacher_video_source(get_post_meta($p->ID,'_dgs_aparat',true));if(!$source||$source['type']!=='aparat')continue;$h.='<article><button type="button" class="dgx-video-play" data-aparat="'.esc_attr($source['embed']).'" data-video-title="'.esc_attr($p->post_title).'">'.(has_post_thumbnail($p)?get_the_post_thumbnail($p,'large',['loading'=>'lazy']):'<span class="dgx-video-placeholder">'.dgs_portal_icon('videos').'</span>').'<span class="dgx-play">▶</span></button><h3>'.esc_html($p->post_title).'</h3><p>'.esc_html($p->post_excerpt).'</p></article>';}$h.='</div>';if(!$q->posts)$h.=dgs_empty('هنوز ویدیویی منتشر نشده است.');return [$h,$q->max_num_pages];}
function dgs_video_preview(){list($cards)=dgs_video_cards(3);return '<section class="dsh-card dgx-video-section">'.dgs_showcase_heading('گالری ویدیوها','videos',dgs_video_url(),'مشاهده همه ویدیوها').$cards.'</section>';}
function dgs_video_page(){$page=max(1,absint(dgs_att_get('video_page','1')));list($cards,$max)=dgs_video_cards(12,$page);return '<div class="dsh-page"><h1>گالری ویدیوهای مدرسه</h1>'.$cards.dgs_catalog_pagination($page,(int)$max,'video_page',dgs_video_url()).'</div>';}
add_shortcode('daneshgaran_videos','dgs_video_page');
add_filter('template_include',function($template){return get_template()==='daneshgaran'&&dgs_video_active()?DGS_PATH.'includes/video-template.php':$template;},115);
add_action('wp_footer',function(){if(!dgs_showcase_active()&&!dgs_video_active())return;echo '<dialog class="dgx-video-dialog"><button type="button" data-video-close aria-label="بستن ویدیو">×</button><h2></h2><div data-video-player></div></dialog>';});
